pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new Owned();
    }

    function testFuzz_property(address caller, address newOwner) public {
        if (caller == address(0)) caller = address(1);

        if (caller != deployer) {
            c.setOwner(caller);
        }

        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(caller == deployer);
        } else {
        }

        assertTrue((!ok) || (c.owner() == deployer));
    }
}
